+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.3rem;
+}
+
+.char-count.at-limit {
+    color: #dc3545;
+    font-weight: 600;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e9ecef;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h4 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.3rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #495057;
+    font-size: 0.9rem;
+}
+
+.review-section dd {
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-description {
+    margin: 0.3rem 0 0;
+    font-size: 0.85rem;
+    color: #6c757d;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    font-size: 0.9rem;
+    margin: 0;
+}
+
+.text-muted {
+    color: #6c757d;
+    font-size: 0.85rem;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.success-icon {
+    width: 64px;
+    height: 64px;
+    border-radius: 50%;
+    background: #198754;
+    color: #fff;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1.5rem;
+}
+
+.submission-confirmation h4 {
+    color: #198754;
+    margin-bottom: 1rem;
+}
+
+/* Responsive */
+@media (max-width: 600px) {
+    .form-row {
+        grid-template-columns: 1fr;
+    }
+
+    .step-indicator {
+        flex-wrap: wrap;
+    }
+
+    .step-label {
+        font-size: 0.65rem;
+    }
+}
+

